  m1275: "Connection retries",
  m1276: "SDK · Before HTTP 200",
  m1277:
    "Connection failures or no HTTP 200 yet: connection reset, read/write timeout, DNS failures, other network errors, and HTTP 408, 429, 500, 502, 503, 504.",
  m1278:
    "Other status codes (400 / 401 / 403 / 404 / 413 / 422, etc.) are deterministic rejections. Retrying would fail again, so they are propagated immediately.",
  m1279:
    "Resends the same request unchanged. Once the stream starts (HTTP 200 received), interruptions are handled by another layer.",
  m1280: "Retry count",
  m1281: "Exponential 0.5s → 1s → 2s (max 8s)",
  m1282: "-1 = no retries; propagate failures immediately",
  m1283: "Empty-response retries",
  m1284: "SDK · OpenAI format only",
  m1285:
    "HTTP 200 with normal stop finish_reason but no content blocks at all. Empty gateway frames, missing reasoning fields, and sampling glitches can cause this.",
  m1286:
    "Excludes empty content caused by max_tokens truncation. Increase the output limit instead; resending would hit the same limit.",
  m1287: "Resends the entire prompt, which is expensive for long contexts. Keep the count low.",
  m1288: "-1 = return empty responses unchanged",
  m1289: "Same-provider safe-window retries",
  m1290: "Application · Before output delivery",
  m1291:
    "Failures after the stream is established (HTTP 200), such as disconnects, provider overload, or in-stream 429/5xx errors, before any token is delivered to the caller.",
  m1292:
    "No retry for exhausted quota (402 / insufficient_quota, handled by profile rotation), long context (413 / context length, handled by compression), or deterministic 400 / 401 / 403 / 404 / 422 rejections.",
  m1293:
    "Replays the same request on the same profile. Since no output was delivered, replay does not duplicate model output or tool execution.",
  m1294: "Exponential 0.5s → 1s (max 4s)",
  m1295: "-1 = pass stream failures to the outer intent rerun layer",
  m1296: "Rotation circuit breaker",
  m1297: "Application · One global process-level state",
  m1298:
    "Transient failures (429, 5xx, network errors) trip the circuit after consecutive failures reach the threshold. Deterministic failures such as insufficient balance (402), invalid keys (401/403), or missing models (404) trip it immediately.",
  m1299: "A single success resets the count, so intermittent failures do not slowly accumulate toward a trip.",
  m1300: "A tripped profile enters cooldown and is skipped by rotation. State is persisted across restarts.",
  m1301: "Consecutive failures before tripping",
  m1302: "Steps: 1 min → 5 min → 30 min",
  m1303: "-1 = never trip on transient failures (deterministic failures still trip)",
  m1304: "Intent reruns",
  m1305:
    "When earlier layers cannot recover, a Worker ends with model_error: inner retries exhausted, or the stream failed after output delivery began, when replay is unsafe and the whole intent must restart.",
  m1306:
    "Quota exhaustion is handled by profile rotation, not reruns here. Paused, terminated, or wrapping-up tasks yield immediately without waiting through backoff.",
  m1307:
    "Reruns the whole intent from the beginning. This is the outermost layer, so each rerun multiplies the attempts of all inner layers.",
  m1308: "Rerun count",
  m1309: "Fixed 3s",
  m1310: "-1 = no reruns; mark the intent blocked immediately",
  m1311: "Trigger",
  m1312: "Not handled here",
  m1313: "Default {p0}",
  m1314: "Interval (ms)",
  m1315: "Default backoff",
  m1316: "Fixed {p0}",
  m1317: "Blank = default; ",
  m1318: "Retry overrides",
  m1319:
    "Overrides global Retry and backoff defaults for this profile only. Blank fields follow global settings; -1 disables that retry layer. An interval replaces exponential backoff with a fixed delay. Circuit breakers and intent reruns are process-wide and can only be changed globally.",
  m1320: "Failed to read retry policy: {p0}",
  m1321: "Saved and effective immediately (the current call still uses its old settings)",
  m1322: "Loading retry policy…",
  m1323: "A failed model call passes through five retry layers, from inside out:",
  m1324: "Connection → Empty response → Same-provider safe window → Rotation circuit breaker → Intent rerun",
  m1325: ". Outer layers run only after inner ones are exhausted, so counts",
  m1326: "multiply",
  m1327:
    ". Setting every layer high can spend dozens of requests on one interruption. Leave all fields blank to keep current defaults and existing behavior. The first three layers can be overridden per model profile.",
  m1328: "Restore all defaults",
  m1329: "Do not send (default)",
  m1330: "max_tokens (default)",
  m1331:
    "Which output-limit key to send. max_tokens is the default and is recognized by most compatible gateways. Official OpenAI reasoning models (o series / GPT-5) require max_completion_tokens and reject max_tokens with unsupported_parameter.",
  m1332: "Only selectable for OpenAI format. Anthropic always uses max_tokens.",
  m1333: "Only selectable for OpenAI format. Responses API always uses max_output_tokens.",
  m1334: "No key configured",
  m1335: "API key missing; calls unavailable",
