  m1645: "Global runtime switches",
  m1646:
    "When enabled, all Agent HTTP traffic passes through the recording proxy and is stored. Agents receive traffic_search / traffic_get tools and proxy settings, including proxy instructions in their prompts.",
  m1647: "When disabled (default), no traffic is recorded. Agents",
  m1648: "do not",
  m1649: "receive proxy settings or traffic tools, and prompts",
