  m1651: "proxy instructions. Switching rebuilds Agents immediately to apply the change.",
  m1652: "Enabled · Recording traffic and injecting proxy settings",
  m1653: "Disabled · No recording or proxy injection",
  m1654: "Agent automatic traffic binding",
  m1655:
    "Off by default. When enabled, the report Agent triggered on vulnerability creation reviews existing HTTP requests/responses and links traffic before writing the report.",
  m1656: "Inspecting packets and making extra tool calls increases token usage.",
  m1657:
    "TCP, uncaptured, or unmatched traffic can still be reported. This does not affect capture, manual binding, or viewing saved evidence. Applies to the next Agent round; disabling immediately rejects new automatic bindings.",
  m1658: "Enabled · Increases token usage",
  m1659: "Disabled · Manual binding remains available",
  m1660: "Global proxy",
  m1661: "All Agents'",
  m1662: "target traffic",
  m1663: "uses this outbound proxy (hide source IP / use a jump host). Supports",
  m1664: "with optional",
  m1665: "authentication. Blank = direct connection.",
  m1666: "is enabled, it acts as the recording proxy's",
  m1667: "upstream",
  m1668:
    "(traffic is still recorded before forwarding). With capture off, proxy settings are injected directly into Agent Bash/WebFetch. Independent of web search and LLM proxies.",
  m1669: ": SOCKS5 with",
  m1670: "capture disabled",
  m1671: "depends on each command-line tool's support for",
  m1672:
    "(curl supports it; some tools may ignore it). For SOCKS5, enabling capture is recommended: the MITM proxy connects directly so tools need no awareness and proxying is reliable.",
