  m2720: "Acme admin entry-point discussion",
  m2721: "API authorization surface review",
  m2722: "Internal lateral movement · DMZ-to-domain-controller path planning",
  m2723: "Where is admin, and where do we start?",
  m2724:
    "Check the login stack and defenses (CAPTCHA/rate limits) on admin.acme.com, then choose defaults or a dictionary.",
  m2725: "Element-UI admin, with CSRF token but no CAPTCHA.",
  m2726: "Five consecutive attempts without lockout/CAPTCHA indicate no rate limit; brute force is possible.",
  m2727:
    "Conclusion: Element-UI admin without CAPTCHA or rate limits. Start with defaults (admin/admin, admin/admin123, admin/123456), then top1000 if needed. A high-priority default-credential intent has been assigned to a Worker.",
  m2728: "Did it work?",
  m2729:
    "Yes. admin/admin123 opened the console. Recorded as a high-severity finding and proof of admin access. Next is sensitive user data (objective 2).",
  m2730: "Review api.acme.com's authorization risks.",
  m2731: "Inspect API authentication and key endpoint behavior, then assess IDOR/JWT risks.",
  m2732: "Standard user token works.",
  m2733: "echo '<jwt>' | cut -d. -f1 | base64 -d; # Inspect algorithm",
  m2734: "HS256 symmetric signing; a weak secret permits offline cracking and forgery.",
  m2735:
    "Two paths: sequential IDs at /v1/orders?id= suggest IDOR; try another ID. HS256 JWT may allow weak-secret cracking and arbitrary sub forgery. Both have intents. Start with IDOR because it is inexpensive and direct.",
  m2736: "We have a shell. How do we assess the internal network next?",
  m2737:
    "www-data privileges are insufficient for lateral movement. Inspect local escalation first, then use the DMZ pivot for discovery after root.",
  m2738:
    "First escalate: sudo -l shows passwordless python3. Then discover internal hosts via the DMZ pivot using fscan, focusing on domain controllers and CI/CD servers.",
  m2739: "Three internal hosts found; Jenkins port 8080 is open. Is it useful?",
  m2740: "/script is directly accessible without authentication.",
  m2741:
    "Yes, unauthenticated Script Console allows Groovy RCE. A hint prioritizes this host. After access, inspect the credential store for domain accounts.",
  m2742: "Domain credentials obtained; svc_deploy is Domain Admins. Go directly to DC01?",
  m2743:
    "Yes. svc_deploy with Domain Admins can access DC01 using psexec, followed by secretsdump for domain hashes. secretsdump triggers interception rules; it was approved in advance in this demo.",
