  m2414:
    "# ScopeWeaver 침투 테스트 보고서 — Acme Corp\n\n## 개요\n- 범위: acme.com(www / admin / api / shop / vpn 하위 도메인 포함)\n- 확인된 발견 사항: 6개(높음 3 · 보통 3 · 낮음 2)\n- 엔진 모드: exploring\n\n## 주요 발견 사항\n1. **[높음] 관리자 기본 비밀번호** admin.acme.com admin/admin123 → 관리자 전체 접근 가능.\n2. **[높음] SQL 주입** www.acme.com/search?q= → acme_prod 데이터베이스 읽기 가능.\n3. **[높음] IDOR** api.acme.com/v1/orders?id= → 전화번호와 주소를 포함한 다른 사용자의 주문 노출.\n4. **[보통] 반사형 XSS**, **.git 소스 노출**, **로그인 속도 제한 없음**.\n\n## 권고 사항\n- 관리자 비밀번호 변경과 MFA를 의무화하고 기본 자격 증명을 금지합니다.\n- 검색에 매개변수화된 쿼리와 출력 인코딩을 사용합니다.\n- API 객체별 권한을 검증하고 강력한 JWT 비밀키로 교체합니다.\n\n> 인터페이스 시연을 위해 모의 데이터로 생성한 데모 보고서입니다.",
