  m1632: "noa コンテキスト圧縮を有効にしました（以降の実行に適用されます）",
  m1633: "noa コンテキスト圧縮を無効にしました（組み込み圧縮に戻しました）",
  m1634: "Web 検索設定を保存しました",
  m1635: "Brave API キーを保存しました",
  m1636: "Tavily API キーを保存しました",
  m1637: "送信プロキシを保存しました",
