  m1641: "検索テストに成功しました · {p0} が {p1} 件の結果を返しました",
  m1642: "検索テストに失敗しました: ",
  m1643: "不明なエラー",
  m1644: "システム設定",
  m1645: "グローバルな実行時スイッチ",
  m1646:
    "有効にすると、すべてのエージェントの HTTP トラフィックが記録プロキシを経由して保存されます。エージェントは traffic_search / traffic_get ツールとプロキシ設定を受け取り、プロンプトにプロキシの指示が含まれます。",
  m1647: "無効（既定）の場合、トラフィックは記録されません。エージェントは",
  m1648: "プロキシ設定もトラフィックツールも",
  m1649: "受け取らず、プロンプトは",
  m1650: "プロキシの指示を",
  m1651: "含みません。切り替えると変更を適用するためにエージェントを即座に再構成します。",
  m1652: "有効 · トラフィックを記録しプロキシ設定を注入",
  m1653: "無効 · 記録もプロキシ注入もなし",
  m1654: "エージェントの自動トラフィック紐付け",
  m1655:
    "既定では無効。有効にすると、脆弱性の登録時に起動するレポートエージェントが既存の HTTP 要求／応答を確認し、レポート作成前にトラフィックを紐付けます。",
  m1656: "パケットの確認と追加のツール呼び出しにより、トークン使用量が増えます。",
  m1657:
    "TCP、未取得、または一致しないトラフィックでも報告できます。これはキャプチャ、手動の紐付け、保存済み証拠の閲覧には影響しません。次のエージェントラウンドに適用され、無効にすると新しい自動紐付けを即座に拒否します。",
  m1658: "有効 · トークン使用量が増えます",
  m1659: "無効 · 手動の紐付けは引き続き利用できます",
  m1660: "グローバルプロキシ",
  m1661: "すべてのエージェントの",
  m1662: "対象トラフィック",
  m1663: "はこの送信プロキシを使用します（送信元 IP を隠す / 踏み台ホストを使う）。対応:",
  m1664: "。任意で",
  m1665: "認証。空欄 = 直接接続。",
  m1666: "が有効な場合、記録プロキシの",
  m1667: "上流",
  m1668:
    "として機能します（転送前に引き続きトラフィックを記録します）。キャプチャがオフの場合、プロキシ設定はエージェントの Bash/WebFetch に直接注入されます。Web 検索や LLM のプロキシとは独立しています。",
  m1669: ": SOCKS5 で",
  m1670: "キャプチャを無効",
  m1671: "にした場合、各コマンドラインツールの次への対応に依存します",
  m1672:
    "（curl は対応しています。一部のツールは無視することがあります）。SOCKS5 ではキャプチャの有効化を推奨します。MITM プロキシが直接接続するためツール側の認識は不要で、プロキシが確実に機能します。",
  m1673: "プロキシ URL",
  m1674: "socks5://user:pass@host:1080 または http://host:port（空欄 = 直接）",
  m1675: "設定済み · すべての対象トラフィックがこのプロキシを使用します",
  m1676: "未設定 · 対象トラフィックは直接接続します",
  m1677: "作業上の制約の注入",
  m1678: "有効にすると、各タスクの",
  m1679:
    "（タスク概要 → 作業上の制約で管理する allow/deny エントリ）が対応するエージェントのシステムプロンプトに含まれ、現在のポートのみをテストする、ブルートフォースを禁止するといった探索の境界を定めます。",
  m1680: "注入は次のそれぞれについて個別に制御できます:",
  m1681: "プランナー",
  m1682: "と",
  m1683: "ワーカー",
  m1684:
    "。既定ではどちらも有効です。変更はエージェントを再構成せず次の読み取りから適用されます。無効にしたエージェントは制約を参照しなくなります。",
  m1685: "プランナーに注入",
  m1686: " · オン",
  m1687: " · オフ",
  m1688: "ワーカーに注入",
  m1689: "実験的機能",
  m1690:
    "まだ検証中の仕組みで、既定では無効です。エージェントの動作や安定性を変える可能性があります。影響を理解したうえで有効にしてください。",
  m1691: "noa コンテキスト圧縮",
  m1692: ": モデル駆動による長い会話履歴の圧縮（norma v0.4.0）。有効にすると、4 種類のエージェント（",
  m1693: "プランナー / ワーカー / メインエージェント / チャット",
  m1694:
    "）が組み込み圧縮の代わりに noa コンテキスト管理を使用します。圧縮前の原文は、確認できるようタスクの作業ディレクトリに保管されます。エージェントを再構成せず以降の実行に適用され、無効にすると即座に組み込み圧縮に戻ります。",
  m1695: "これは Web 検索の",
  m1696: "マスタースイッチおよびソース設定",
  m1697: "です。有効にしたら、",
  m1698: "各エージェントの設定",
  m1699: "で個別に有効化してください",
  m1700: "（返すのはタイトル、リンク、抜粋のみです。本文は WebFetch が取得します）。Web 検索は記録プロキシを",
  m1701: "使用せず",
  m1702: "、トラフィックキャプチャとは独立しています。",
  m1703: "利用できるソース:",
  m1704: "（キー不要）、",
  m1705: "Brave（無料プラン）",
  m1706: "（Brave API キーが必要）、",
  m1707: "（Tavily API キーが必要）、または",
  m1708:
    "（現在の LLM プロファイルを再利用）。マスタースイッチがオフの場合、エージェントごとの Web 検索の切り替えは利用できません。",
  m1709: "マスタースイッチがオン · 各エージェントの設定で個別に有効化してください",
  m1710: "オフ · エージェントは Web 検索を有効にできません",
