  m1712: "ソースを選択",
  m1713: "DuckDuckGo（ddgs · 無料、キー不要）",
  m1714: "Brave（無料プラン · キーが必要）",
  m1715: "Tavily（キーが必要）",
  m1716: "DeepSeek（公式）",
  m1717: "公式 DeepSeek Web 検索",
  m1718: "このソースは次を直接再利用します:",
  m1719: "現在有効な LLM プロファイル",
  m1720: "。そのため",
  m1721: "公式の DeepSeek モデルのみに対応",
  m1722: "し、そのプロファイルは",
  m1723: "Anthropic プロトコルを使用している必要があります",
  m1724:
    "。DeepSeek の OpenAI プロトコルのエンドポイントはサーバー側検索に対応していません。LLM プロファイルを切り替えると、このソースが使えなくなることがあります。",
