  m2412: "サイドクエスチョンのデータの解析に失敗しました。パネルを開き直してください",
  m2413: "認証されていません",
  m2414:
    "# ScopeWeaver 侵入テストレポート — Acme Corp\n\n## 概要\n- スコープ: acme.com（www / admin / api / shop / vpn サブドメインを含む）\n- 確認済みの発見事項: 6（高 3 · 中 3 · 低 2）\n- エンジンモード: 探索中\n\n## 主な発見事項\n1. **[高] デフォルトの管理者パスワード** admin.acme.com admin/admin123 → 管理者権限を完全に取得。\n2. **[高] SQL インジェクション** www.acme.com/search?q= → acme_prod への読み取りアクセス。\n3. **[高] IDOR** api.acme.com/v1/orders?id= → 電話番号や住所を含む他ユーザーの注文が露出。\n4. **[中] 反射型 XSS**、**.git ソースの露出**、**ログインのレート制限なし**。\n\n## 推奨事項\n- 管理者パスワードの変更と MFA を必須にし、デフォルト認証情報を禁止する。\n- パラメータ化された検索クエリと出力エンコードを使用する。\n- オブジェクトレベルの API 認可を強制し、脆弱な JWT シークレットを置き換える。\n\n> インターフェースのデモ専用に、モックデータから生成したデモレポートです。",
