  m2436: "api.acme.com の注文・ユーザーエンドポイントにおける IDOR とインジェクションのリスクを評価する。",
  m2437: "shop.acme.com の決済・注文ワークフロー",
  m2438: "決済・注文エンドポイントにおける認可、金額改ざん、競合状態のリスクを評価する。",
  m2439: "外部露出の偵察（VPN / 境界サービス）",
  m2440: "acme.com が露出している悪用可能な境界サービスを特定する。",
