  m2506: "shop.acme.com のコンポーネントのフィンガープリンティングと CVE 突き合わせ",
  m2507: "ショップのデシリアライズ RCE を発火させ、リバースシェルを取得する",
  m2508: "DMZ のローカル情報を収集し、root に昇格する",
