  m2717: "reports/summary.md の書き込みに成功。\n68 文字を書き込みました。",
  m2718: "バックアップテーブルの目的を確認。削除の前に確認すること。",
  m2719: "[Model] バックアップテーブルの可能性。本番データを含むかどうか確認できない。",
  m2720: "Acme 管理画面の入口の議論",
  m2721: "API 認可面のレビュー",
  m2722: "内部の横展開 · DMZ からドメインコントローラーへの経路計画",
  m2723: "管理画面はどこにあり、どこから始めますか？",
  m2724: "admin.acme.com のログインスタックと防御（CAPTCHA/レート制限）を確認し、デフォルトか辞書かを選びます。",
  m2725: "Element-UI の管理画面。CSRF トークンはあるが CAPTCHA はない。",
  m2726: "ロックアウト／CAPTCHA なしで 5 回連続試行できることは、レート制限がないことを示す。ブルートフォースが可能。",
  m2727:
    "結論: CAPTCHA やレート制限のない Element-UI 管理画面。デフォルト（admin/admin、admin/admin123、admin/123456）から始め、必要なら top1000 を試す。高優先度のデフォルト認証情報の意図をワーカーに割り当て済み。",
  m2728: "うまくいきましたか？",
