  m2730: "api.acme.com の認可リスクをレビューしてください。",
  m2731: "API の認証と主要エンドポイントの挙動を確認し、IDOR/JWT のリスクを評価します。",
  m2732: "標準ユーザーのトークンが機能する。",
  m2734: "HS256 の対称署名。脆弱なシークレットによりオフラインでの解読と偽造が可能。",
  m2735:
    "2 つの経路: /v1/orders?id= の連番 ID は IDOR を示唆。別の ID を試す。HS256 の JWT は脆弱なシークレットの解読と任意の sub 偽造を許す可能性。どちらにも意図あり。安価で直接的なため IDOR から始める。",
  m2736: "シェルを取得しました。次に内部ネットワークをどう評価しますか？",
  m2737: "www-data の権限は横展開には不十分です。まずローカル昇格を確認し、root の後に DMZ ピボットで発見を行います。",
  m2738:
    "まず昇格: sudo -l がパスワード不要の python3 を示す。次に fscan を使い DMZ ピボット経由で内部ホストを発見し、ドメインコントローラーと CI/CD サーバーに注力する。",
  m2739: "内部ホストが 3 件見つかり、Jenkins のポート 8080 が開いています。役に立ちますか？",
  m2740: "/script が認証なしで直接アクセス可能。",
