  m2744: "目標を達成しました。チェーンを要約してください。",
  m2745:
    "完全なチェーン:\n1. .git の露出 → ソースレビューとハードコードされた認証情報\n2. ショップの Fastjson RCE → DMZ のリバースシェル\n3. sudo 昇格 → root の足がかり\n4. 内部発見 → DC01/FS01/Jenkins\n5. 認証なしの Jenkins → svc_deploy のドメイン認証情報\n6. Kerberoasting → svc_sql のパスワード\n7. Domain Admins の svc_deploy → psexec で DC01 → secretsdump でドメインハッシュ\n\n4 つの目標すべてを達成。発見事項は 17 件（高 7 / 中 4 / 低 2 + 内部チェーン 8 件）。",
